interface Image {
    void display();
}

final class RealImage implements Image {
    private final String file;
    private final byte[] pixels;

    RealImage(String file) {
        this.file = file;
        this.pixels = loadFromDisk(file); // expensive: 50-200ms + MBs
    }

    @Override public void display() { render(pixels); }

    private static byte[] loadFromDisk(String f) { /* ... */ return new byte[0]; }
    private static void render(byte[] p) { /* ... */ }
}

final class ImageProxy implements Image {
    private final String file;
    private volatile RealImage real; // volatile: safe publication for DCL

    ImageProxy(String file) { this.file = file; }

    @Override public void display() {
        RealImage r = real;
        if (r == null) {
            synchronized (this) {
                r = real;
                if (r == null) {
                    r = new RealImage(file);
                    real = r;
                }
            }
        }
        r.display(); // identical interface: client never knows
    }
}

interface DocumentStore {
    byte[] read(String docId, User user);
}

final class AccessProxy implements DocumentStore {
    private final DocumentStore real;
    private final Authorizer authz;
    private final Cache<String, byte[]> cache;

    AccessProxy(DocumentStore real, Authorizer authz, Cache<String, byte[]> cache) {
        this.real = real; this.authz = authz; this.cache = cache;
    }

    @Override public byte[] read(String docId, User user) {
        if (!authz.allow(user, "read:" + docId))
            throw new SecurityException("denied: " + docId);
        // Never key cache by docId alone when auth matters.
        String key = user.tenant() + ":" + docId;
        byte[] hit = cache.get(key);
        if (hit != null) return hit;
        byte[] fresh = real.read(docId, user);
        cache.put(key, fresh,Ttl.seconds(30));
        return fresh;
    }
}
interface Authorizer { boolean allow(User u, String perm); }
interface Cache<K,V> { V get(K k); void put(K k, V v, Ttl t); }
record User(String id, String tenant()) {}
enum Ttl { seconds(int s){ return null; } }
